public enum FfiEffect {
    
    case commitText(text: String
    )
    case setComposing(text: String, caret: UInt32, 
        /**
         * 지금 사람이 손대고 있는 구간(코드포인트 [시작, 끝)) — 변환의 주목 문절이다.
         * 셸은 이 값이 있을 때 조합 구간의 선택 범위로 옮긴다.
         */focusStart: UInt32?, focusEnd: UInt32?
    )
    case clearComposing
    case deleteBackward(codePoints: UInt32
    )
    case updateCandidates(candidates: [FfiCandidate]
    )
    case moveCursor(offset: Int32
    )
    /**
     * 밀리초 뒤에 `timer_fired`를 부르라는 요청. 앞선 타이머는 갈아 끼운다 —
     * 끄는 명령은 없다(이미 끝난 주기에 울린 타이머는 아무 일도 하지 않는다).
     */
    case setTimer(milliseconds: UInt32
    )
}


#if compiler(>=6)
extension FfiEffect: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiEffect: FfiConverterRustBuffer {
    typealias SwiftType = FfiEffect

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiEffect {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .commitText(text: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .setComposing(text: try FfiConverterString.read(from: &buf), caret: try FfiConverterUInt32.read(from: &buf), focusStart: try FfiConverterOptionUInt32.read(from: &buf), focusEnd: try FfiConverterOptionUInt32.read(from: &buf)
        )
        
        case 3: return .clearComposing
        
        case 4: return .deleteBackward(codePoints: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 5: return .updateCandidates(candidates: try FfiConverterSequenceTypeFfiCandidate.read(from: &buf)
        )
        
        case 6: return .moveCursor(offset: try FfiConverterInt32.read(from: &buf)
        )
        
        case 7: return .setTimer(milliseconds: try FfiConverterUInt32.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiEffect, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .commitText(text):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(text, into: &buf)
            
        
        case let .setComposing(text,caret,focusStart,focusEnd):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(text, into: &buf)
            FfiConverterUInt32.write(caret, into: &buf)
            FfiConverterOptionUInt32.write(focusStart, into: &buf)
            FfiConverterOptionUInt32.write(focusEnd, into: &buf)
            
        
        case .clearComposing:
            writeInt(&buf, Int32(3))
        
        
        case let .deleteBackward(codePoints):
            writeInt(&buf, Int32(4))
            FfiConverterUInt32.write(codePoints, into: &buf)
            
        
        case let .updateCandidates(candidates):
            writeInt(&buf, Int32(5))
            FfiConverterSequenceTypeFfiCandidate.write(candidates, into: &buf)
            
        
        case let .moveCursor(offset):
            writeInt(&buf, Int32(6))
            FfiConverterInt32.write(offset, into: &buf)
            
        
        case let .setTimer(milliseconds):
            writeInt(&buf, Int32(7))
            FfiConverterUInt32.write(milliseconds, into: &buf)
            
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeFfiEffect_lift(_ buf: RustBuffer) throws -> FfiEffect {
    return try FfiConverterTypeFfiEffect.lift(buf)
}

